10:   @override
11:   State<CurrencyListPage> createState() => _CurrencyListPageState();
12: }
13: 
14: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
15:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
16: 
17:   late final AnimationController _fadeController;
18: 
19:   late Future<List<CurrencyModel>> _currencyListFuture;
20: 
21:   List<CurrencyModel> _allCurrencies = [];
22: 
23:   RefreshController? _refreshController;
24: 
25:   @override
26:   void initState() {
27:     super.initState();
28:     _initAnimation();
29:     // Инициализируем пустым списком, чтобы ValueListenableBuilder не упал.
30:     _filteredCurrenciesNotifier = ValueNotifier<List<CurrencyModel>>([]);
31:     _subscribeToRefresh();
32:     _initData();
33:   }
34: 
35:   @override
36:   void dispose() {
37:     _filteredCurrenciesNotifier.dispose();
38:     _fadeController.dispose();
39:     _refreshController?.removeListener(_onRefreshTrigger);
40:     super.dispose();
41:   }
42: 
43:   void _subscribeToRefresh() {
44:     _refreshController = context.read<RefreshController>();
45:     _refreshController!.addListener(_onRefreshTrigger);
46:   }
47: 
48:   void _onRefreshTrigger() {
49:     if (_refreshController!.value) {
50:       setState(() {
51:         _initData(forceNetwork: true);
52:       });
53:     }
54:   }
55: 
56:   void _initAnimation() {
57:     _fadeController = AnimationController(
58:       duration: Duration(milliseconds: 400),
59:       vsync: this,
60:     );
61:   }
62: 
63:   void _initData({bool forceNetwork = false}) {
64:     final currencyRepository = context.read<CurrencyRepository>();
65: 
66:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
67:       final List<CurrencyModel> value = page.items;
68:       _allCurrencies = value;
69:       _filteredCurrenciesNotifier.value = value;
70: 
71:       if (forceNetwork) {
72:         _fadeController.forward(); // запускаем анимацию при обновлении
73:       }
74: 
75:       currencyRepository.saveCurrencyList(value);
76: 
77:       return value;
78:     });
79:   }
80: 
81:   void _filterCurrencies(String query) {
82:     final String lowerQuery = query.toLowerCase();
83:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
84:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
85:     });
86: 
87:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
88:   }
89: 
90:   @override
91:   Widget build(BuildContext context) {
92:     return Scaffold(
93:       appBar: AppBar(title: Text(context.loc.currencyRate)),
94:       body: FutureBuilder(
95:         future: _currencyListFuture,
96:         builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
97:           final List<CurrencyModel>? data = snapshot.data;
98:           if (data == null) return const SizedBox.shrink();
99: 
100:           return FadeTransition(
101:             opacity: _fadeController.view,
102:             child: Column(
103:               children: [
104:                 Padding(
105:                   padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
106:                   child: SearchView(onChanged: _filterCurrencies),
107:                 ),
108:                 Expanded(
109:                   child: ValueListenableBuilder<List<CurrencyModel>>(
110:                     valueListenable: _filteredCurrenciesNotifier,
111:                     builder: (BuildContext context, List<CurrencyModel> data, _) {
112:                       return ListView.builder(
113:                         itemCount: data.length,
114:                         itemBuilder: (BuildContext context, int index) {
115:                           final CurrencyModel currency = data[index];
116: 
117:                           return Padding(
118:                             key: ValueKey(currency.id),
119:                             padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
120:                             child: CurrencyCard(model: currency),
121:                           );
122:                         },
123:                         padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
124:                       );
125:                     },
126:                   ),
127:                 ),
128:               ],
129:             ),
130:           );
131:         },
132:       ),
133:     );
134:   }
135: }

